    let team = null;
    let teamName = null;
    let confidence = 0;
    
    // 1. 角球识别
    if (text.includes('角球') || lowerText.includes('corner')) {
      eventType = 'corner';
      confidence = 0.95;
    }
    // 2. 危险任意球
    else if (text.includes('任意球') && (text.includes('危险') || text.includes('威胁') || lowerText.includes('dangerous'))) {
      eventType = 'dangerous_freekick';
      confidence = 0.9;
    }
    // 3. 普通任意球
    else if (text.includes('任意球') || lowerText.includes('freekick')) {
      eventType = 'freekick';
      confidence = 0.7;
    }
    // 4. 危险进攻
    else if (text.includes('危险进攻') || lowerText.includes('dangerous attack')) {
      eventType = 'dangerous_attack';
      confidence = 0.85;
    }
    // 5. 进攻
    else if (text.includes('进攻') || lowerText.includes('attack')) {
      eventType = 'attack';
      confidence = 0.75;
    }
    // 6. 控球
    else if (text.includes('控球')) {
      eventType = 'possession';
      confidence = 0.8;
    }
    // 7. 进球
    else if (text.includes('进球') || text.includes('破门') || lowerText.includes('goal') || lowerText.includes('score')) {
      eventType = 'goal';
      confidence = 0.98;
    }
    // 8. 过半场
    else if (text.includes('过半场') || text.includes('半场')) {
      eventType = 'cross_halfway';
      confidence = 0.7;
    }

    if (!eventType) return null;

    // 识别球队
    const teamMatch = text.match(/\(([^)]+)\)/);
    const textTeamName = teamMatch ? teamMatch[1] : '';

