    const matchId = getMatchId();
    const eventInfo = classifyEvent(text, teams);
    
    if (!eventInfo) return;
    
    const { eventType, team, teamName, confidence } = eventInfo;
    
    const eventKey = getEventKey(eventType, team, minute);
    
    if (isDuplicate(matchId, eventKey)) {
      return;
    }
    
    const inTimeWindow = shouldAlert(minute);
    const oddsCheck = checkOddsValid();
    
    // ===== 角球/危险任意球 - 主信号 =====
